import {api,DEMO,uid} from './api.js';
const $=s=>document.querySelector(s),root=$('#app'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const diff={easy:'Cơ bản',medium:'Trung bình',hard:'Nâng cao'},status={draft:'Bản nháp',published:'Đã xuất bản',archived:'Đã ẩn',in_progress:'Đang làm',submitted:'Đã nộp',expired:'Hết giờ'};
let user=null,subjects=[],exams=[],questions=[],history=[],current=null,qindex=0,timer,renderId=0,busy=false,saveQueue=Promise.resolve(),failedSaves=new Map();
const subject=id=>subjects.find(s=>s.id===id)?.name||'Môn học';
const fmt=n=>n===null||n===undefined?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:1});
const date=s=>new Date(s).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4000)}
function go(route){location.hash=route}
const route=()=>location.hash.slice(1)||'/dashboard';
const pill=(s,cls='')=>`<span class="pill ${cls}">${esc(s)}</span>`;
function dialog(title,body){modal.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="close" aria-label="Đóng">×</button></div><div class="modalbody">${body}</div>`;modal.querySelector('.close').onclick=()=>modal.close();modal.showModal()}
async function action(btn,fn){if(btn.disabled)return;btn.disabled=true;try{await fn()}catch(e){if(modal.open){let el=modal.querySelector('.error');if(!el){el=document.createElement('p');el.className='error';el.setAttribute('role','alert');modal.querySelector('.modalbody').append(el)}el.textContent=e.message}else toast(e.message)}finally{if(btn.isConnected)btn.disabled=false}}
function formError(form,e){let el=form.querySelector('.error');if(!el){el=document.createElement('p');el.className='error';el.setAttribute('role','alert');form.append(el)}el.textContent=e.message}
function onForm(id,fn){
  $(id).onsubmit=async e=>{
    e.preventDefault();
    const f=e.target,b=f.querySelector('[type=submit]');
    if(f.dataset.submitting==='true'||b.disabled)return;
    const data=new FormData(f),controls=Array.from(f.elements),disabled=controls.map(el=>el.disabled);
    f.dataset.submitting='true';f.setAttribute('aria-busy','true');
    const error=f.querySelector('.error');if(error)error.textContent='';
    controls.forEach(el=>{el.disabled=true});
    try{await fn(data,f)}catch(error){formError(f,error)}finally{
      controls.forEach((el,i)=>{el.disabled=disabled[i]});
      delete f.dataset.submitting;f.removeAttribute('aria-busy');
    }
  }
}
function shell(content){const admin=user.role==='admin';const links=admin?[['/dashboard','◫','Tổng quan'],['/admin/subjects','▦','Môn học'],['/admin/questions','☷','Ngân hàng câu hỏi'],['/admin/exams','▤','Quản lý đề thi'],['/admin/stats','◷','Thống kê']]:[['/dashboard','◫','Tổng quan'],['/exams','▤','Khám phá đề thi'],['/history','◷','Lịch sử làm bài'],['/profile','○','Tài khoản']];const path=route();root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="logo" href="#/dashboard"><span class="logo-mark">S</span>SmartExam<span style="font-size:10px;color:#bad29d;align-self:start">®</span></a><div><p class="navlabel">${admin?'QUẢN TRỊ HỆ THỐNG':'KHÔNG GIAN HỌC TẬP'}</p><nav>${links.map(([p,i,n])=>`<a class="navlink ${path===p?'active':''}" href="#${p}"><span class="navicon">${i}</span>${n}</a>`).join('')}</nav></div><div class="sidebox"><strong>${admin?'Kiến thức tạo nên giá trị.':'Mỗi ngày một tiến bộ.'}</strong>${admin?'Xây dựng những bài thi chất lượng để học tập hiệu quả hơn.':'Một bài luyện tập hôm nay, một bước tự tin cho ngày mai.'}</div><div class="profile"><span class="avatar">${esc(user.name.split(' ').pop().slice(0,1))}</span><div style="font-size:12px"><strong>${esc(user.name)}</strong><small>${admin?'Quản trị viên':'Sinh viên'}</small></div><button class="logout" id="logout" aria-label="Đăng xuất" title="Đăng xuất">↪</button></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="mobile-menu" id="menubtn" aria-label="Mở menu">☰</button>Không gian ${admin?'quản trị':'học tập'} <span style="margin:0 9px">/</span><b style="color:var(--ink)">${links.find(x=>x[0]===path)?.[2]||'Bài thi'}</b></div><div class="top-right">${DEMO?'<span class="demo">Bản demo</span>':''}<span class="date">${new Date().toLocaleDateString('vi-VN',{day:'numeric',month:'long',year:'numeric'})}</span><span class="avatar" style="width:30px;height:30px;font-size:11px">${admin?'AD':'SV'}</span></div></header><div class="workspace">${content}<footer class="footer"><span>© 2026 SmartExam · Học chủ động, vững tương lai.</span><span>${DEMO?'Dữ liệu mẫu · lưu trên trình duyệt này':'Kết nối Backend'}</span></footer></div></main></div>`;$('#logout').onclick=()=>{api.logout();sessionStorage.removeItem('smartexam.session');user=null;go('/login');render()};$('#menubtn').onclick=()=>$('.layout').classList.toggle('menu-open')}
function head(title,sub='',button='',eyebrow='SmartExam'){return `<div class="pagehead"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="sub">${sub}</p></div>${button}</div>`}
function metrics(items){return `<div class="metrics">${items.map(([label,n,suffix])=>`<div class="metric"><div class="label">${label}</div><strong>${n}</strong><small>${suffix||''}</small></div>`).join('')}</div>`}
function empty(title,desc){return `<div class="empty"><span style="font-size:30px">▤</span><strong>${title}</strong><span>${desc}</span></div>`}
function auth(register=false){clearInterval(timer);root.innerHTML=`<div class="auth"><section class="authbrand"><a class="logo" href="#/login"><span class="logo-mark">S</span>SmartExam</a><div><span class="eyebrow" style="color:var(--lime)">LEARN. PRACTICE. GROW.</span><h1>Kiến thức hôm nay.<br><span>Tự tin ngày mai.</span></h1><p>Không gian luyện tập dành cho bạn.<br>Chủ động học, kiểm tra kiến thức và theo dõi<br>sự tiến bộ qua từng bài thi.</p><div class="hero-art"><div class="orbit"></div><div class="orbit second"></div><div class="book">S</div><span class="star">✦</span></div></div><p style="font-size:12px">SmartExam · Dự án học tập CNTT</p></section><section class="authform"><span class="eyebrow">CHÀO MỪNG ĐẾN SMARTEXAM</span><h2>${register?'Tạo tài khoản mới':'Sẵn sàng để tiến bộ?'}</h2><p class="sub" style="margin-bottom:28px">${register?'Bắt đầu hành trình học tập của bạn.':'Đăng nhập để tiếp tục hành trình học tập của bạn.'}</p><form id="auth-form" class="form">${register?'<label>Họ và tên<input name="name" required autocomplete="name" placeholder="Nhập họ và tên"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email" value="${register?'':DEMO?'student@smartexam.vn':''}" placeholder="ban@example.com"></label><label>Mật khẩu<input name="password" type="password" required minlength="${register?8:6}" autocomplete="${register?'new-password':'current-password'}" value="${!register&&DEMO?'demo123':''}" placeholder="${register?'Từ 8 đến 128 ký tự':'Tối thiểu 6 ký tự'}"></label>${register?'<label>Nhập lại mật khẩu<input name="confirm" type="password" required minlength="8" autocomplete="new-password"></label>':''}<div class="error" role="alert"></div><button type="submit" class="btn">${register?'Đăng ký tài khoản':'Đăng nhập'} <span>↗</span></button></form><p class="sub" style="text-align:center;margin-top:22px">${register?'Đã có tài khoản?':'Bạn chưa có tài khoản?'} <a class="textbtn" href="#/${register?'login':'register'}">${register?'Đăng nhập':'Đăng ký ngay'}</a></p>${DEMO?`<div class="authnote"><b>Trải nghiệm bản demo</b><br>Sinh viên: student@smartexam.vn / demo123<br>Admin: admin@smartexam.vn / admin123<br><span>Tài khoản đăng ký mới dùng mật khẩu demo123 khi đăng nhập demo.</span><div class="row" style="margin-top:8px"><button type="button" class="textbtn" id="demo-student">Dùng Sinh viên</button><button type="button" class="textbtn" id="demo-admin">Dùng Admin</button></div></div>`:''}</section></div>`;onForm('#auth-form',async(d,f)=>{if(register){
const name=d.get('name').trim(),email=d.get('email').trim(),password=d.get('password');
if(Array.from(name).length<1||Array.from(name).length>120)throw Error('Họ và tên cần từ 1 đến 120 ký tự.');
if(!email||email.length>254)throw Error('Email cần đúng định dạng và tối đa 254 ký tự.');
if(Array.from(password).length<8||Array.from(password).length>128||!password.trim())throw Error('Mật khẩu cần từ 8 đến 128 ký tự và không chỉ gồm khoảng trắng.');
if(password!==d.get('confirm'))throw Error('Mật khẩu nhập lại chưa khớp.');
await api.register({name,email,password});
f.elements.password.value='';f.elements.confirm.value='';toast(DEMO?'Tạo tài khoản thành công. Dùng mật khẩu demo123 để đăng nhập demo.':'Đăng ký thành công. Vui lòng đăng nhập.');go('/login')}else{const session=await api.login(d.get('email').trim(),d.get('password'));user=session.user;if(DEMO)sessionStorage.setItem('smartexam.session',JSON.stringify(session));go('/dashboard')}});if(DEMO){$('#demo-student').onclick=()=>{const f=$('#auth-form');f.elements.email.value='student@smartexam.vn';f.elements.password.value='demo123'};$('#demo-admin').onclick=()=>{const f=$('#auth-form');f.elements.email.value='admin@smartexam.vn';f.elements.password.value='admin123'}}}
function examCard(e,i=0){const colors=[['#e8eedc','#53713d','JS'],['#e1ecec','#4b7777','SQL'],['#eee5dc','#956f46','Ag']][i%3];return `<article class="card"><div class="cardtop" style="--tint:${colors[0]};--tone:${colors[1]}"><span class="subject-icon">${colors[2]}</span>${pill(diff[e.difficulty]||'Trung bình')}</div><div class="cardbody"><span class="eyebrow" style="font-size:9px;letter-spacing:1.3px">${esc(subject(e.subject_id))}</span><h3>${esc(e.title)}</h3><p>${esc(e.description||'Ôn tập kiến thức và đánh giá năng lực của bạn.')}</p><div class="meta"><span>◷ ${e.duration_minutes} phút</span><span>▤ ${e.question_count??e.questions.length} câu hỏi</span></div><div class="cardfoot"><span>Đạt từ ${e.pass_score} điểm</span><button class="btn small start" data-id="${e.id}">Luyện tập <span>↗</span></button></div></div></article>`}
function bindStart(){document.querySelectorAll('.start').forEach(b=>b.onclick=()=>dialog('Trước khi bắt đầu',`<p class="sub">${esc(exams.find(e=>e.id===b.dataset.id).title)}</p><p class="sub">Thời gian được tính ngay khi bắt đầu. Đáp án tự động lưu sau mỗi lần chọn. Bạn có thể tải lại trang để tiếp tục.</p><p class="sub">Số lượt đã dùng: ${exams.find(e=>e.id===b.dataset.id).used_attempts??0}/${exams.find(e=>e.id===b.dataset.id).max_attempts}</p><div class="row" style="margin-top:24px"><button class="btn" id="confirm-start" data-id="${b.dataset.id}">Bắt đầu làm bài ↗</button><button class="btn secondary" id="cancel-start">Để sau</button></div>`))}
// One delegated handler is installed below for modal actions.

document.addEventListener('click',e=>{if(e.target.id==='cancel-start')modal.close();if(e.target.id==='confirm-start'){const b=e.target;const exam=exams.find(x=>x.id===b.dataset.id);action(b,async()=>{const a=await api.start(exam.id);modal.close();go('/attempt/'+a.id)})}});
async function dashboard(){const admin=user.role==='admin';if(admin){shell(head('Tổng quan hệ thống','Quản lý nội dung và theo dõi hoạt động học tập.','<a class="btn" href="#/admin/exams">Quản lý đề thi ↗</a>','QUẢN TRỊ')+metrics([['Môn học',subjects.length],['Ngân hàng câu hỏi',questions.length,'câu'],['Đề đang mở',exams.filter(e=>e.status==='published').length,'đề'],['Đề nháp',exams.filter(e=>e.status==='draft').length,'đề']])+`<div class="featured"><section><div class="sectiontitle"><h2>Đề thi gần đây</h2><a href="#/admin/exams" class="textbtn">Xem tất cả ↗</a></div>${examTable(exams.slice(0,5))}</section><section><div class="sectiontitle"><h2>Quy trình biên soạn</h2></div><div class="panel"><div class="activity"><b>01 · Xây dựng kiến thức</b><br><span class="muted">Tạo môn học và ngân hàng câu hỏi.</span></div><div class="activity"><b>02 · Thiết kế bài kiểm tra</b><br><span class="muted">Chọn câu, gán điểm và thời lượng.</span></div><div class="activity"><b>03 · Xuất bản & theo dõi</b><br><span class="muted">Mở đề và xem thống kê kết quả.</span></div></div></section></div>`);bindExamActions();return}const done=history.filter(a=>a.status!=='in_progress'),avg=done.length?done.reduce((s,a)=>s+a.score,0)/done.length:null;const active=history.find(a=>a.status==='in_progress');shell(head(`Chào ${esc(user.name.split(' ').pop())}, cùng học nhé!`,'Một chút luyện tập mỗi ngày, tiến gần hơn đến mục tiêu.','', 'KHÔNG GIAN CỦA BẠN')+`<section class="hero"><div><span class="eyebrow">HỌC CHỦ ĐỘNG · VỮNG TƯƠNG LAI</span><h2>Chinh phục kiến thức,<br>theo cách của bạn.</h2><p>Lựa chọn bài thi phù hợp, kiểm tra những gì đã học và nhìn thấy sự tiến bộ của chính mình.</p><a class="btn" href="#/${active?'attempt/'+active.id:'exams'}">${active?'Tiếp tục bài đang làm':'Khám phá đề thi'} ↗</a></div><div class="hero-art"><div class="orbit"></div><div class="orbit second"></div><div class="book">S</div><span class="star">✦</span></div></section>`+metrics([['Đề thi khả dụng',exams.length,'đề'],['Bài thi hoàn thành',done.length,'bài'],['Điểm trung bình',fmt(avg),'/ 100'],['Bài thi đạt',done.filter(a=>a.passed).length,'bài']])+`<div class="sectiontitle"><h2>Đề xuất cho bạn</h2><a href="#/exams" class="textbtn">Tất cả đề thi ↗</a></div><div class="grid">${exams.slice(0,3).map(examCard).join('')||empty('Chưa có đề thi','Admin sẽ sớm cập nhật đề mới.')}</div><div class="sectiontitle"><h2>Hoạt động gần đây</h2><a href="#/history" class="textbtn">Xem lịch sử ↗</a></div>${historyTable(history.slice(0,4))}`);bindStart()}
function filters(admin=false){return `<div class="filters"><input id="search" type="search" aria-label="Tìm kiếm" placeholder="⌕  Tìm kiếm theo tên hoặc nội dung..."><select id="filter-subject" aria-label="Lọc môn học"><option value="">Tất cả môn học</option>${subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><select id="filter-diff" aria-label="Lọc độ khó"><option value="">Tất cả độ khó</option>${Object.entries(diff).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select>${admin?'<select id="filter-status" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option><option value="draft">Bản nháp</option><option value="published">Đã xuất bản</option><option value="archived">Đã ẩn</option></select>':''}</div>`}
function bindFilters(list,draw){const apply=()=>{const s=$('#search').value.toLocaleLowerCase('vi'),sub=$('#filter-subject').value,d=$('#filter-diff').value,st=$('#filter-status')?.value;draw(list.filter(x=>(x.title||x.text||'').toLocaleLowerCase('vi').includes(s)&&(!sub||x.subject_id===sub)&&(!d||x.difficulty===d)&&(!st||x.status===st)))};['search','filter-subject','filter-diff','filter-status'].forEach(id=>{if($('#'+id))$('#'+id).addEventListener(id==='search'?'input':'change',apply)})}
function examList(){shell(head('Khám phá đề thi','Luyện tập đúng trọng tâm. Sẵn sàng cho mọi bài kiểm tra.','', 'THƯ VIỆN LUYỆN TẬP')+filters()+`<p class="sub" id="count" style="margin-bottom:16px">${exams.length} đề thi dành cho bạn</p><div id="exam-grid" class="grid"></div>`);const draw=list=>{$('#exam-grid').innerHTML=list.map(examCard).join('')||empty('Không tìm thấy đề thi','Thử thay đổi từ khóa hoặc bộ lọc.');$('#count').textContent=`${list.length} đề thi dành cho bạn`;bindStart()};draw(exams);bindFilters(exams,draw)}
function historyTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>ĐỀ THI</th><th>THỜI GIAN</th><th>ĐIỂM</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><b>${esc(a.title)}</b></td><td>${date(a.started_at)}</td><td><b>${fmt(a.score)}</b>${a.score!==undefined?' / 100':''}</td><td>${pill(a.status==='in_progress'?'Đang làm':a.passed?'Đạt':'Chưa đạt',a.status==='in_progress'?'warn':a.passed?'good':'bad')}</td><td><a class="textbtn" href="#/${a.status==='in_progress'?'attempt':'result'}/${a.id}">${a.status==='in_progress'?'Tiếp tục':'Xem kết quả'} ↗</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="panel">${empty('Hành trình của bạn bắt đầu từ đây','Chọn một đề thi để ghi nhận kết quả đầu tiên.')}<div style="text-align:center"><a class="btn" href="#/exams">Khám phá đề thi ↗</a></div></div>`}
function historyPage(){shell(head('Lịch sử làm bài','Mỗi lần luyện tập là một bước tiến của bạn.')+`<div class="filters"><input id="history-search" type="search" placeholder="Tìm tên đề thi..." aria-label="Tìm lịch sử"><select id="history-status" aria-label="Lọc kết quả"><option value="">Tất cả kết quả</option><option value="active">Đang làm</option><option value="pass">Đạt</option><option value="fail">Chưa đạt</option></select></div><div id="history-table">${historyTable(history)}</div>`);const draw=()=>{$('#history-table').innerHTML=historyTable(history.filter(a=>a.title.toLowerCase().includes($('#history-search').value.toLowerCase())&&(!$('#history-status').value||($('#history-status').value==='active'?a.status==='in_progress':a.status!=='in_progress'&&a.passed===($('#history-status').value==='pass')))))};$('#history-search').oninput=draw;$('#history-status').onchange=draw}
function profile(){shell(head('Tài khoản của bạn','Thông tin hồ sơ được cung cấp từ hệ thống.')+`<div class="panel" style="max-width:650px"><div class="row"><span class="avatar" style="width:65px;height:65px;font-size:24px">${esc(user.name.slice(-1))}</span><div><h2 style="margin:0 0 6px">${esc(user.name)}</h2>${pill(user.role==='admin'?'Quản trị viên':'Sinh viên','good')}</div></div><div class="activity" style="margin-top:20px"><span class="muted">Email</span><br>${esc(user.email)}</div><div class="activity"><span class="muted">Mã tài khoản</span><br>${esc(user.id)}</div><p class="sub" style="margin-top:20px">Liên hệ quản trị viên nếu cần cập nhật thông tin tài khoản.</p></div>`)}
async function attemptPage(id){current=await api.attempt(id);if(current.status!=='in_progress'){go('/result/'+id);return}qindex=Math.min(qindex,current.snapshot.questions.length-1);drawAttempt();timer=setInterval(tick,500);tick()}
function flags(){try{return JSON.parse(localStorage.getItem('flags.'+current.id))||[]}catch{return []}}
function drawAttempt(){const a=current,exam=a.snapshot,q=exam.questions[qindex],done=Object.keys(a.answers).length,fl=flags();shell(head(esc(exam.title),`${esc(subject(exam.subject_id))} · ${exam.questions.length} câu hỏi · Điểm đạt: ${exam.pass_score}/100`,'','PHIÊN LUYỆN TẬP')+`<div class="exam-layout"><section class="panel"><div class="row space"><span class="eyebrow">CÂU ${qindex+1} / ${exam.questions.length}</span><button class="textbtn" id="flag">${fl.includes(q.id)?'★ Đã đánh dấu':'☆ Đánh dấu xem lại'}</button></div><h2 class="question">${esc(q.text)}</h2><div id="answers">${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="answer" value="${o.id}" ${a.answers[q.id]===o.id?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(o.text)}</span></label>`).join('')}</div><p id="save-status" class="statusline" role="status">${failedSaves.size?'Có đáp án chưa lưu. Hãy chọn lại để thử lưu.':'Đáp án được tự động lưu khi bạn chọn.'}</p><div class="row space" style="border-top:1px solid var(--line);padding-top:20px;margin-top:20px"><button class="btn secondary" id="prev" ${qindex===0?'disabled':''}>← Câu trước</button><button class="btn" id="next" ${qindex===exam.questions.length-1?'disabled':''}>Câu tiếp theo →</button></div></section><aside class="panel examinfo"><span class="eyebrow">THỜI GIAN CÒN LẠI</span><div class="timer" id="timer">--:--</div><p class="sub" id="answered-count">Đã trả lời ${done}/${exam.questions.length} câu</p><div class="progress"><i style="width:${100*done/exam.questions.length}%"></i></div><div class="qnav">${exam.questions.map((x,i)=>`<button class="qnum ${a.answers[x.id]?'answered':''} ${i===qindex?'current':''} ${fl.includes(x.id)?'flagged':''}" data-i="${i}" aria-label="Câu ${i+1}">${i+1}</button>`).join('')}</div><p class="sub" style="font-size:11px">Xanh: đã chọn · Gạch vàng: xem lại</p><button class="btn" id="submit" style="width:100%;margin-top:15px">Nộp bài ↗</button><p class="sub" style="font-size:11px;margin-top:12px">Tải lại trang vẫn giữ thời gian và đáp án đã lưu.</p></aside></div>`);document.querySelectorAll('[name=answer]').forEach(r=>r.onchange=()=>{const value=r.value;a.answers[q.id]=value;const el=$('#save-status');el.textContent='Đang lưu đáp án...';$('#answered-count').textContent=`Đã trả lời ${Object.keys(a.answers).length}/${exam.questions.length} câu`;document.querySelector(`.qnum[data-i="${qindex}"]`).classList.add('answered');document.querySelector('.progress i').style.width=(100*Object.keys(a.answers).length/exam.questions.length)+'%';failedSaves.set(q.id,value);saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{await api.answer(a.id,q.id,value);if(failedSaves.get(q.id)===value)failedSaves.delete(q.id);if(el.isConnected)el.textContent='✓ Đã lưu đáp án'}catch(e){if(el.isConnected)el.textContent='Lưu thất bại. Chọn lại đáp án để thử lại.';toast(e.message)}})});$('#prev').onclick=()=>{qindex--;drawAttempt();tick()};$('#next').onclick=()=>{qindex++;drawAttempt();tick()};document.querySelectorAll('.qnum').forEach(b=>b.onclick=()=>{qindex=+b.dataset.i;drawAttempt();tick()});$('#flag').onclick=()=>{const f=flags(),i=f.indexOf(q.id);i<0?f.push(q.id):f.splice(i,1);localStorage.setItem('flags.'+a.id,JSON.stringify(f));drawAttempt();tick()};$('#submit').onclick=()=>{dialog('Bạn muốn nộp bài?',`<p class="sub">Đã chọn ${Object.keys(a.answers).length}/${exam.questions.length} câu. Sau khi nộp, bạn không thể thay đổi đáp án.</p><div class="row" style="margin-top:22px"><button class="btn" id="do-submit">Xác nhận nộp bài</button><button class="btn secondary" id="back-exam">Tiếp tục làm</button></div>`);$('#back-exam').onclick=()=>modal.close();$('#do-submit').onclick=e=>action(e.target,()=>submit(false))}}
function tick(){if(!current||!$('#timer'))return;const ms=Number.isFinite(Number(current.deadline_at))?Number(current.deadline_at):Date.parse(current.deadline_at),seconds=Math.max(0,Math.ceil((ms-Date.now())/1000));$('#timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('#timer').classList.toggle('low',seconds<60);if(seconds===0&&!busy)submit(true).catch(e=>toast(e.message))}
async function submit(expired){if(busy)return;busy=true;try{await saveQueue;if(failedSaves.size&&!expired)throw Error('Còn đáp án chưa lưu. Vui lòng chọn lại đáp án bị lỗi trước khi nộp.');await api.submit(current.id);clearInterval(timer);modal.close();failedSaves.clear();go('/result/'+current.id);toast(expired?'Đã hết giờ. Hệ thống chốt các đáp án đã lưu.':'Nộp bài thành công.')}finally{busy=false}}
async function resultPage(id){const a=await api.result(id),e=a.snapshot;shell(head('Kết quả bài thi',esc(e.title),'<a class="btn secondary" href="#/history">← Lịch sử làm bài</a>')+`<div class="panel result">${pill(a.passed?'HOÀN THÀNH · ĐẠT':'HOÀN THÀNH · CHƯA ĐẠT',a.passed?'good':'warn')}<h2 style="font-size:25px;margin-bottom:6px">${a.passed?'Làm tốt lắm, tiếp tục phát huy!':'Mỗi lần luyện tập là một cơ hội.'}</h2><p class="sub">${a.passed?'Bạn đã vượt qua mức điểm yêu cầu của bài thi.':'Xem lại lời giải và thử sức lần nữa khi sẵn sàng.'}</p><div class="score">${fmt(a.score)}<small>TRÊN 100 ĐIỂM</small></div><div class="row" style="justify-content:center;gap:32px"><p class="sub">Số câu đúng<br><b style="color:var(--ink)">${a.correct_count}/${e.questions.length}</b></p><p class="sub">Điểm yêu cầu<br><b style="color:var(--ink)">${e.pass_score}/100</b></p><p class="sub">Trạng thái<br><b style="color:var(--ink)">${status[a.status]}</b></p></div><div class="row" style="justify-content:center;margin-top:20px"><a href="#/exams" class="btn">Luyện tập tiếp ↗</a><button class="btn secondary" id="review-toggle">Xem đáp án & lời giải</button></div></div><section id="review" hidden><div class="sectiontitle"><h2>Xem lại bài làm</h2></div><div class="panel">${e.questions.map((q,i)=>`<article class="reviewitem"><b>Câu ${i+1}. ${esc(q.text)}</b><p class="sub">${q.points} điểm trọng số · ${a.answers[q.id]?'Đã trả lời':'Chưa trả lời'}</p>${q.options.map(o=>`<div class="reviewanswer ${o.is_correct?'correct':a.answers[q.id]===o.id?'wrong':''}">${o.is_correct?'✓ ':a.answers[q.id]===o.id?'× ':''}${esc(o.text)} ${a.answers[q.id]===o.id?'<b> · Bạn chọn</b>':''}</div>`).join('')}<p class="sub"><b>Giải thích:</b> ${esc(q.explanation||'Chưa có lời giải.')}</p></article>`).join('')}</div></section>`);$('#review-toggle').onclick=()=>{$('#review').hidden=!$('#review').hidden;if(!$('#review').hidden)$('#review').scrollIntoView({behavior:'smooth'})}}
function subjectPage(){shell(head('Quản lý môn học','Xây dựng danh mục kiến thức cho hệ thống.','<button class="btn" id="add-subject">+ Thêm môn học</button>','QUẢN TRỊ')+`<div class="tablewrap"><table><thead><tr><th>MÔN HỌC</th><th>SLUG</th><th>CÂU HỎI</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${subjects.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.slug)}</td><td>${questions.filter(q=>q.subject_id===s.id).length}</td><td>${pill(s.is_active?'Đang mở':'Đã ẩn',s.is_active?'good':'warn')}</td><td><button class="textbtn edit-subject" data-id="${s.id}">Chỉnh sửa ↗</button></td></tr>`).join('')}</tbody></table></div>`);$('#add-subject').onclick=()=>subjectForm();document.querySelectorAll('.edit-subject').forEach(b=>b.onclick=()=>subjectForm(subjects.find(s=>s.id===b.dataset.id)))}
function subjectForm(s={}){dialog(s.id?'Chỉnh sửa môn học':'Thêm môn học',`<form id="subject-form" class="form"><label>Tên môn học<input name="name" value="${esc(s.name)}" required maxlength="100"></label><label>Slug<input name="slug" value="${esc(s.slug)}" pattern="[a-z0-9]+(-[a-z0-9]+)*" required placeholder="vi-du-mon-hoc"></label><label class="checkline"><input type="checkbox" name="active" ${s.is_active!==false?'checked':''}>Mở cho sinh viên</label><button class="btn" type="submit">Lưu môn học</button></form>`);const f=$('#subject-form');f.elements.name.oninput=()=>{if(!s.id)f.elements.slug.value=f.elements.name.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')};onForm('#subject-form',async d=>{await api.saveSubject({...(s.id?{id:s.id}:{}),name:d.get('name').trim(),slug:d.get('slug'),is_active:d.has('active')});modal.close();toast('Đã lưu môn học');render()})}
function questionTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>CÂU HỎI</th><th>MÔN HỌC</th><th>ĐỘ KHÓ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${list.map(q=>`<tr><td style="max-width:430px"><b>${esc(q.text)}</b><br><span class="muted">${q.options.length} phương án</span></td><td>${esc(subject(q.subject_id))}</td><td>${diff[q.difficulty]}</td><td>${pill(q.is_active?'Đang dùng':'Đã ẩn',q.is_active?'good':'warn')}</td><td><button class="textbtn edit-question" data-id="${q.id}">Xem / sửa ↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('Không có câu hỏi phù hợp','Thêm câu hỏi hoặc thay đổi bộ lọc.')}
function questionPage(){shell(head('Ngân hàng câu hỏi','Biên soạn nội dung, phương án và lời giải.','<button class="btn" id="add-question">+ Thêm câu hỏi</button>','QUẢN TRỊ')+filters()+`<div id="question-table"></div>`);const draw=list=>{$('#question-table').innerHTML=questionTable(list);document.querySelectorAll('.edit-question').forEach(b=>b.onclick=()=>questionForm(questions.find(q=>q.id===b.dataset.id)))};draw(questions);bindFilters(questions,draw);$('#add-question').onclick=()=>questionForm()}
function subjectOptions(id){return subjects.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${esc(s.name)}</option>`).join('')}
function questionForm(q={}){if(!subjects.length){toast('Hãy tạo môn học trước.');return}const locked=q.id&&exams.some(e=>e.status==='published'&&e.questions.some(x=>x.question_id===q.id));dialog(q.id?'Chi tiết câu hỏi':'Thêm câu hỏi',`${locked?'<div class="notice">Câu hỏi đã thuộc đề xuất bản nên bị khóa sửa. Bạn có thể tạo câu hỏi mới để thay thế ở đề nháp.</div>':''}<form id="question-form" class="form"><fieldset ${locked?'disabled':''} style="border:0;padding:0;margin:0;display:grid;gap:17px"><div class="formrow"><label>Môn học<select name="subject_id">${subjectOptions(q.subject_id)}</select></label><label>Độ khó<select name="difficulty">${Object.entries(diff).map(([k,v])=>`<option value="${k}" ${k===(q.difficulty||'medium')?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Nội dung câu hỏi<textarea name="text" required maxlength="2000">${esc(q.text)}</textarea></label><span class="sub" style="font-size:12px">Chọn vòng tròn ở phương án đúng (2–6 phương án).</span><div id="option-list"></div><button class="btn secondary small" type="button" id="add-option">+ Thêm phương án</button><label>Lời giải<textarea name="explanation" required>${esc(q.explanation)}</textarea></label><label class="checkline"><input name="active" type="checkbox" ${q.is_active!==false?'checked':''}>Câu hỏi đang hoạt động</label></fieldset>${locked?'':'<button class="btn" type="submit">Lưu câu hỏi</button>'}</form>`);let options=cloneOptions(q.options||[{text:'',is_correct:true},{text:'',is_correct:false}]);function drawOptions(){$('#option-list').innerHTML=options.map((o,i)=>`<div class="optionrow" style="margin-bottom:9px"><input type="radio" name="correct" value="${i}" aria-label="Phương án ${i+1} đúng" ${o.is_correct?'checked':''} required ${locked?'disabled':''}><input class="option-text" data-i="${i}" required value="${esc(o.text)}" aria-label="Nội dung phương án ${i+1}" ${locked?'disabled':''}><button type="button" class="close remove-option" data-i="${i}" ${options.length<=2||locked?'disabled':''} aria-label="Xóa phương án ${i+1}">×</button></div>`).join('');$('#add-option').disabled=locked||options.length>=6;document.querySelectorAll('.option-text').forEach(x=>x.oninput=()=>options[+x.dataset.i].text=x.value);document.querySelectorAll('[name=correct]').forEach(x=>x.onchange=()=>options.forEach((o,i)=>o.is_correct=i===+x.value));document.querySelectorAll('.remove-option').forEach(b=>b.onclick=()=>{options.splice(+b.dataset.i,1);drawOptions()})}drawOptions();$('#add-option').onclick=()=>{options.push({text:'',is_correct:false});drawOptions()};if(!locked)onForm('#question-form',async d=>{if(options.some(o=>!o.text.trim()))throw Error('Phương án không được để trống.');await api.saveQuestion({...(q.id?{id:q.id}:{}),subject_id:d.get('subject_id'),difficulty:d.get('difficulty'),text:d.get('text').trim(),explanation:d.get('explanation').trim(),is_active:d.has('active'),options:options.map(o=>({...o,id:o.id||uid()}))});modal.close();toast('Đã lưu câu hỏi');render()})}
const cloneOptions=x=>x.map(o=>({...o}));
function examTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>ĐỀ THI</th><th>THỜI LƯỢNG</th><th>CÂU HỎI</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${list.map(e=>`<tr><td><b>${esc(e.title)}</b><br><span class="muted">${esc(subject(e.subject_id))}</span></td><td>${e.duration_minutes} phút</td><td>${e.questions.length}</td><td>${pill(status[e.status],e.status==='published'?'good':'warn')}</td><td>${e.status==='draft'?`<button class="textbtn edit-exam" data-id="${e.id}">Sửa</button><button class="textbtn publish-exam" data-id="${e.id}">Xuất bản</button>`:e.status==='published'?`<button class="textbtn archive-exam" data-id="${e.id}">Ẩn đề</button>`:'<span class="muted">Đã lưu trữ</span>'}</td></tr>`).join('')}</tbody></table></div>`:empty('Không có đề thi phù hợp','Tạo một đề nháp để bắt đầu.')}
function adminExams(){shell(head('Quản lý đề thi','Tạo bài kiểm tra phù hợp và kiểm soát xuất bản.','<button class="btn" id="add-exam">+ Tạo đề thi</button>','QUẢN TRỊ')+filters(true)+`<div id="exam-table"></div>`);const draw=list=>{$('#exam-table').innerHTML=examTable(list);bindExamActions()};draw(exams);bindFilters(exams,draw);$('#add-exam').onclick=()=>examForm()}
function bindExamActions(){document.querySelectorAll('.edit-exam').forEach(b=>b.onclick=()=>examForm(exams.find(e=>e.id===b.dataset.id)));for(const [cls,st]of [['publish-exam','published'],['archive-exam','archived']])document.querySelectorAll('.'+cls).forEach(b=>b.onclick=()=>{dialog(st==='published'?'Xuất bản đề thi?':'Ẩn đề thi?',`<p class="sub">${st==='published'?'Sinh viên có thể bắt đầu làm bài. Cấu trúc đề và câu hỏi sẽ bị khóa sửa.':'Đề sẽ không xuất hiện trong danh sách để bắt đầu lượt mới. Lịch sử bài làm vẫn được giữ.'}</p><div class="row" style="margin-top:20px"><button class="btn" id="confirm-status">Xác nhận</button></div>`);$('#confirm-status').onclick=e=>action(e.target,async()=>{await api.examStatus(b.dataset.id,st);modal.close();toast('Đã cập nhật trạng thái đề');render()})})}
function examForm(e={}){if(!subjects.length){toast('Hãy tạo môn học và câu hỏi trước.');return}let selected=(e.questions||[]).map(q=>({...q}));dialog(e.id?'Chỉnh sửa đề nháp':'Tạo đề thi nháp',`<form id="exam-form" class="form"><label>Tên đề thi<input name="title" required maxlength="150" value="${esc(e.title)}"></label><label>Mô tả<textarea name="description">${esc(e.description)}</textarea></label><div class="formrow"><label>Môn học<select name="subject_id" id="exam-subject">${subjectOptions(e.subject_id)}</select></label><label>Độ khó<select name="difficulty">${Object.entries(diff).map(([k,v])=>`<option value="${k}" ${k===(e.difficulty||'medium')?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="formrow"><label>Thời lượng (phút)<input type="number" name="duration_minutes" min="1" max="300" required value="${e.duration_minutes||30}"></label><label>Điểm đạt / 100<input type="number" name="pass_score" min="0" max="100" required value="${e.pass_score??70}"></label></div><label>Số lượt thi tối đa<input type="number" name="max_attempts" min="1" max="100" required value="${e.max_attempts||3}"></label><div><b style="font-size:13px">Chọn câu hỏi và trọng số</b><p class="sub" style="font-size:12px">Thứ tự chọn là thứ tự trong đề. Dùng ↑ ↓ để sắp xếp.</p><div id="chosen"></div><input type="search" id="builder-search" placeholder="Tìm câu hỏi..." aria-label="Tìm câu hỏi cho đề" style="width:100%;margin-top:10px"><div id="builder"></div></div><button type="submit" class="btn">Lưu bản nháp</button></form>`);const sub=$('#exam-subject');function draw(){const search=$('#builder-search').value.toLowerCase();$('#builder').innerHTML=questions.filter(q=>q.subject_id===sub.value&&q.is_active&&!selected.some(s=>s.question_id===q.id)&&q.text.toLowerCase().includes(search)).map(q=>`<label class="builderitem"><input type="checkbox" data-add="${q.id}"><span>${esc(q.text)}</span></label>`).join('')||'<p class="sub">Không có câu hỏi chưa chọn phù hợp.</p>';$('#chosen').innerHTML=selected.map((x,i)=>`<div class="builderitem"><span><b>${i+1}.</b> ${esc(questions.find(q=>q.id===x.question_id)?.text)}</span><input type="number" min="0.1" max="100" step="0.1" required value="${x.points}" data-points="${i}" aria-label="Trọng số câu ${i+1}"><button type="button" class="textbtn" data-up="${i}" ${i===0?'disabled':''} aria-label="Đưa câu ${i+1} lên">↑</button><button type="button" class="textbtn" data-down="${i}" ${i===selected.length-1?'disabled':''} aria-label="Đưa câu ${i+1} xuống">↓</button><button type="button" class="textbtn" data-remove="${i}" aria-label="Bỏ câu ${i+1}">×</button></div>`).join('');modal.querySelectorAll('[data-add]').forEach(b=>b.onchange=()=>{selected.push({question_id:b.dataset.add,points:1});draw()});modal.querySelectorAll('[data-points]').forEach(b=>b.oninput=()=>selected[+b.dataset.points].points=+b.value);modal.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.splice(+b.dataset.remove,1);draw()});for(const [attr,offset] of [['up',-1],['down',1]])modal.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>{const i=+b.dataset[attr];[selected[i],selected[i+offset]]=[selected[i+offset],selected[i]];draw()})}sub.onchange=()=>{selected=[];draw()};$('#builder-search').oninput=draw;draw();onForm('#exam-form',async d=>{if(selected.some(q=>!Number.isFinite(q.points)||q.points<=0))throw Error('Trọng số điểm phải lớn hơn 0.');await api.saveExam({...(e.id?{id:e.id}:{}),title:d.get('title').trim(),description:d.get('description'),subject_id:d.get('subject_id'),difficulty:d.get('difficulty'),duration_minutes:+d.get('duration_minutes'),pass_score:+d.get('pass_score'),max_attempts:+d.get('max_attempts'),questions:selected});modal.close();toast('Đã lưu đề nháp');render()})}
async function statsPage(){const rows=await Promise.all(exams.map(async e=>({e,s:await api.stats(e.id)})));const completed=rows.reduce((n,x)=>n+x.s.completed,0),total=rows.reduce((n,x)=>n+x.s.total_attempts,0);shell(head('Thống kê kết quả','Theo dõi hoạt động thi và chất lượng học tập.','','QUẢN TRỊ')+metrics([['Tổng lượt thi',total,'lượt'],['Đã hoàn thành',completed,'lượt'],['Điểm trung bình',completed?fmt(rows.reduce((n,x)=>n+(x.s.average_score||0)*x.s.completed,0)/completed):'—','/ 100'],['Tỷ lệ đạt',completed?fmt(rows.reduce((n,x)=>n+(x.s.pass_rate||0)*x.s.completed,0)/completed):'—','%']])+`<div class="panel"><div class="sectiontitle" style="margin-top:0"><h2>Điểm trung bình theo đề</h2></div>${rows.length?rows.map(({e,s})=>`<div class="chartrow"><span>${esc(e.title)}</span><div class="bar"><i style="width:${s.average_score||0}%"></i></div><b>${fmt(s.average_score)}</b></div>`).join(''):empty('Chưa có đề thi','Tạo đề thi để theo dõi kết quả.')}</div><div class="sectiontitle"><h2>Chi tiết theo đề thi</h2></div><div class="tablewrap"><table><thead><tr><th>ĐỀ THI</th><th>LƯỢT THI</th><th>HOÀN THÀNH</th><th>ĐIỂM TRUNG BÌNH</th><th>TỶ LỆ ĐẠT</th></tr></thead><tbody>${rows.map(({e,s})=>`<tr><td><b>${esc(e.title)}</b></td><td>${s.total_attempts}</td><td>${s.completed}</td><td>${fmt(s.average_score)}</td><td>${fmt(s.pass_rate)}${s.pass_rate!==null?'%':''}</td></tr>`).join('')}</tbody></table></div><p class="sub" style="margin-top:15px;font-size:12px">Điểm trung bình và tỷ lệ đạt tính trên các lượt đã nộp hoặc hết giờ. Dấu — nghĩa là chưa có lượt hoàn thành.</p>`)}
async function render(){const rid=++renderId;clearInterval(timer);if(modal.open)modal.close();const path=route();if(!user){auth(path==='/register');return}if(['/login','/register'].includes(path)){go('/dashboard');return}if(path.startsWith('/admin')&&user.role!=='admin'){shell(head('Không có quyền truy cập','Trang này chỉ dành cho quản trị viên.')+'<a class="btn" href="#/dashboard">Về tổng quan</a>');return}try{root.innerHTML='<div class="loading">Đang tải không gian của bạn...</div>';const admin=user.role==='admin';[subjects,exams]=await Promise.all([api.subjects(admin),api.exams(admin)]);if(admin)questions=await api.questions();else history=await api.history();if(rid!==renderId)return;if(path==='/dashboard')await dashboard();else if(path==='/exams'&&!admin)examList();else if(path==='/history'&&!admin)historyPage();else if(path==='/profile')profile();else if(path.startsWith('/attempt/')&&!admin)await attemptPage(path.split('/')[2]);else if(path.startsWith('/result/')&&!admin)await resultPage(path.split('/')[2]);else if(path==='/admin/subjects')subjectPage();else if(path==='/admin/questions')questionPage();else if(path==='/admin/exams')adminExams();else if(path==='/admin/stats')await statsPage();else shell(head('Không tìm thấy trang','Đường dẫn không hợp lệ.')+'<a class="btn" href="#/dashboard">Về tổng quan</a>')}catch(e){if(user)shell(head('Không thể tải dữ liệu',esc(e.message))+'<button class="btn" id="retry">Thử lại</button>');else auth();if($('#retry'))$('#retry').onclick=render;toast(e.message)}}
window.addEventListener('hashchange',render);window.addEventListener('session-expired',()=>{user=null;go('/login');toast('Phiên đăng nhập hết hạn. Vui lòng đăng nhập lại.')});
try{const session=JSON.parse(sessionStorage.getItem('smartexam.session'));if(session)user=await api.restore(session)}catch{sessionStorage.removeItem('smartexam.session')}
render();
